use super::*;
use crate::demo_space_projection;
use crate::engine::space::SpaceCommand;
use crate::engine::space::unit_tests::context::{apply_mutations, studio_emit};
use semio_framework_os::{ArtifactKindSpec, MediaClass, MediaForm, MediaPortDirection, MediaType, MediaWireFormat, register_artifact_descriptor};

#[semio_framework_async_macros::async_test]
async fn space_command_op_text_round_trips_every_variant() {
    store::os_store::test_support::assert_op_line_round_trip(&SpaceCommand::ConnectMediaPorts(ConnectMediaPorts { source_node_id: "n1".into(), source_port_id: "n1:out:out".into(), target_node_id: "n2".into(), target_port_id: "n2:in:in".into() }));
    store::os_store::test_support::assert_op_line_round_trip(&SpaceCommand::DisconnectMediaEdge(crate::engine::space::commands::disconnect_media_edge::DisconnectMediaEdge { edge_id: "e1".into() }));
}

#[semio_framework_async_macros::async_test]
async fn connect_media_ports_rejects_incompatible_types_via_notice() {
    register_artifact_descriptor(&ArtifactKindSpec {
        id: "test.contract.2d".into(),
        label: semio_framework_plugin::LocalizedLabel::native("Test 2D", "Test 2D"),
        source_format: "test.2d".into(),
        component_kind: "test".into(),
        dimension: "2d".into(),
        media_capability: semio_framework_os::OsMediaCapability::MeshOnly,
        media_type: MediaType { class: MediaClass::TwoD, form: MediaForm::Vector },
        schema: "test.contract.2d.schema".into(),
        export_formats: vec!["svg".into()],
        import_formats: vec!["svg".into()],
        export_stdio_kinds: vec![],
        import_stdio_kinds: vec![],
    });
    register_artifact_descriptor(&ArtifactKindSpec {
        id: "test.contract.3d".into(),
        label: semio_framework_plugin::LocalizedLabel::native("Test 3D", "Test 3D"),
        source_format: "test.3d".into(),
        component_kind: "test".into(),
        dimension: "3d".into(),
        media_capability: semio_framework_os::OsMediaCapability::MeshOnly,
        media_type: MediaType { class: MediaClass::ThreeD, form: MediaForm::Mesh },
        schema: "test.contract.3d.schema".into(),
        export_formats: vec!["glb".into()],
        import_formats: vec!["glb".into()],
        export_stdio_kinds: vec![],
        import_stdio_kinds: vec![],
    });
    let mut projection = demo_space_projection().await;
    let src_out = crate::engine::space::unit_tests::context::test_port("contract-src", "out", MediaPortDirection::Out, MediaType { class: MediaClass::TwoD, form: MediaForm::Vector }, "test.contract.2d").await;
    let dst_in = crate::engine::space::unit_tests::context::test_port("contract-dst", "in", MediaPortDirection::In, MediaType { class: MediaClass::ThreeD, form: MediaForm::Mesh }, "test.contract.3d").await;
    projection.graph.nodes.push(crate::engine::space::unit_tests::context::test_node("contract-src", vec![], vec![src_out]).await);
    projection.graph.nodes.push(crate::engine::space::unit_tests::context::test_node("contract-dst", vec![dst_in], vec![]).await);
    let config = SpaceConfig::default();
    let emit = studio_emit(
        &projection,
        &config,
        &SpaceCommand::ConnectMediaPorts(ConnectMediaPorts { source_node_id: "contract-src".into(), source_port_id: "contract-src:out:out".into(), target_node_id: "contract-dst".into(), target_port_id: "contract-dst:in:in".into() }),
    )
    .await
    .expect("handle");
    assert!(emit.artifact_mutations.is_empty(), "an incompatible connect must not push WorkflowMutation::ConnectPorts");
    assert!(matches!(emit.effects.first(), Some(semio_framework_plugin::Effect::Notify { .. })), "an incompatible connect must surface a Notify effect instead");
}

#[semio_framework_async_macros::async_test]
async fn connect_media_ports_negotiates_a_contract_for_compatible_types() {
    register_artifact_descriptor(&ArtifactKindSpec {
        id: "test.contract.doc-a".into(),
        label: semio_framework_plugin::LocalizedLabel::native("Test Doc A", "Testdokument A"),
        source_format: "test.doc".into(),
        component_kind: "test".into(),
        dimension: "data".into(),
        media_capability: semio_framework_os::OsMediaCapability::MeshOnly,
        media_type: MediaType { class: MediaClass::Data, form: MediaForm::Value },
        schema: "test.contract.doc.schema".into(),
        export_formats: vec![],
        import_formats: vec![],
        export_stdio_kinds: vec![],
        import_stdio_kinds: vec![],
    });
    register_artifact_descriptor(&ArtifactKindSpec {
        id: "test.contract.doc-b".into(),
        label: semio_framework_plugin::LocalizedLabel::native("Test Doc B", "Testdokument B"),
        source_format: "test.doc".into(),
        component_kind: "test".into(),
        dimension: "data".into(),
        media_capability: semio_framework_os::OsMediaCapability::MeshOnly,
        media_type: MediaType { class: MediaClass::Data, form: MediaForm::Value },
        schema: "test.contract.doc.schema".into(),
        export_formats: vec![],
        import_formats: vec![],
        export_stdio_kinds: vec![],
        import_stdio_kinds: vec![],
    });
    let mut projection = semio_framework_os::empty_workflow_snapshot().await;
    let src_out = crate::engine::space::unit_tests::context::test_port("contract-src-2", "out", MediaPortDirection::Out, MediaType { class: MediaClass::Data, form: MediaForm::Value }, "test.contract.doc-a").await;
    let dst_in = crate::engine::space::unit_tests::context::test_port("contract-dst-2", "in", MediaPortDirection::In, MediaType { class: MediaClass::Data, form: MediaForm::Value }, "test.contract.doc-b").await;
    projection.graph.nodes.push(crate::engine::space::unit_tests::context::test_node("contract-src-2", vec![], vec![src_out]).await);
    projection.graph.nodes.push(crate::engine::space::unit_tests::context::test_node("contract-dst-2", vec![dst_in], vec![]).await);
    let config = SpaceConfig::default();
    let emit = studio_emit(
        &projection,
        &config,
        &SpaceCommand::ConnectMediaPorts(ConnectMediaPorts { source_node_id: "contract-src-2".into(), source_port_id: "contract-src-2:out:out".into(), target_node_id: "contract-dst-2".into(), target_port_id: "contract-dst-2:in:in".into() }),
    )
    .await
    .expect("handle");
    let edge = emit
        .artifact_mutations
        .iter()
        .find_map(|operation| match operation {
            WorkflowMutation::ConnectPorts(connect) if connect.edge.source_node_id == "contract-src-2" => Some(connect.edge.clone()),
            _ => None,
        })
        .expect("a compatible connect must push WorkflowMutation::ConnectPorts with a negotiated contract");
    assert_eq!(edge.contract.kind_id, "test.contract.doc-b");
    assert_eq!(edge.contract.wire, MediaWireFormat::Document { schema: "test.contract.doc.schema".into() });
    assert!(edge.contract.conversion.is_none());
    let next = apply_mutations(&projection, &emit.artifact_mutations).await;
    assert!(semio_framework_os::validate_workflow(&next.graph).ok, "a freshly negotiated edge must pass validate_workflow's contract-consistency check");
}

